import { useRef, useState } from 'react'
import {
  getServiceTypeList,
  addServiceType,
  editServiceType,
  deleteServiceType,
  updateServiceTypeStatus,
  SystemConfigTypes
} from '@/apis/admin/system-config'
import ExcelTable from '@/components/exportExcel'
import {
  ActionType,
  ProColumns,
  ModalForm,
  ProFormText,
  ProFormDigit,
  ProFormSelect
} from '@ant-design/pro-components'
import { Button, Popconfirm, message, Tag, Space, Tooltip } from 'antd'
import {
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  CheckCircleOutlined,
  StopOutlined,
  ExclamationCircleOutlined,
  AppstoreOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'

// 状态映射
const statusMap: Record<number, { text: string; color: string }> = {
  1: { text: '启用', color: 'success' },
  2: { text: '禁用', color: 'default' }
}

const ServiceCategory: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const [modalVisible, setModalVisible] = useState(false)
  const [modalTitle, setModalTitle] = useState('新增服务类别')
  const [editingRecord, setEditingRecord] = useState<SystemConfigTypes.ServiceTypeListDto | null>(
    null
  )
  const [formSubmitting, setFormSubmitting] = useState(false)

  // 打开新增弹窗
  const handleAdd = () => {
    handleReset()
    setModalTitle('新增服务类别')
    setModalVisible(true)
  }

  // 打开编辑弹窗
  const handleEdit = (record: SystemConfigTypes.ServiceTypeListDto) => {
    setEditingRecord(record)
    setModalTitle('编辑服务类别')
    setModalVisible(true)
  }

  // 保存服务类别
  const handleSave = async (values: any) => {
    setFormSubmitting(true)
    try {
      if (editingRecord) {
        // 编辑
        const res = await editServiceType(editingRecord.id, {
          id: editingRecord.id,
          name: values.name,
          sort: values.sort,
          status: values.status,
          remark: values.remark || ''
        })
        if (res.code === ResultEnum.SUCCESS) {
          message.success('保存成功')
          setModalVisible(false)
          handleReset()
          actionRef.current?.reload()
        } else {
          message.error('保存失败')
        }
      } else {
        // 新增
        const res = await addServiceType({
          name: values.name,
          sort: values.sort,
          status: values.status,
          remark: values.remark || ''
        })
        if (res.code === ResultEnum.SUCCESS) {
          message.success('新增成功')
          setModalVisible(false)
          actionRef.current?.reload()
        } else {
          message.error('新增失败')
        }
      }
    } catch (e) {
      console.error('保存服务类别失败:', e)
      message.error('操作失败')
    } finally {
      setFormSubmitting(false)
    }
  }

  // 更新状态
  const handleUpdateStatus = async (
    record: SystemConfigTypes.ServiceTypeListDto,
    newStatus: number
  ) => {
    try {
      // 如果有关联商品且要禁用，给出警告
      if (newStatus === 2 && record.goodsNum > 0) {
        message.warning(`该类别已关联 ${record.goodsNum} 个商品，禁用后将不可用于新建/编辑商品`)
      }

      const res = await updateServiceTypeStatus(record.id, { id: record.id })
      if (res.code === ResultEnum.SUCCESS) {
        message.success(newStatus === 1 ? '启用成功' : '禁用成功')
        actionRef.current?.reload()
        handleReset()
      } else {
        message.error('操作失败')
      }
    } catch (e) {
      console.error('更新状态失败:', e)
      message.error('操作失败')
    }
  }

  // 删除服务类别
  const handleDelete = async (record: SystemConfigTypes.ServiceTypeListDto) => {
    try {
      const res = await deleteServiceType(record.id, { id: record.id })
      if (res.code === ResultEnum.SUCCESS) {
        message.success('删除成功')
        actionRef.current?.reload()
      } else {
        message.error('删除失败')
      }
    } catch (e) {
      console.error('删除服务类别失败:', e)
      message.error('操作失败')
    }
  }

  // 重置表单
  const handleReset = () => {
    setEditingRecord(null)
  }

  // 表格列定义
  const columns: ProColumns<SystemConfigTypes.ServiceTypeListDto>[] = [
    {
      title: '类别ID',
      dataIndex: 'id',
      key: 'id',
      width: 100,
      hideInSearch: true,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>{text}</span>
      )
    },
    {
      title: '类别名称',
      dataIndex: 'name',
      key: 'name',
      width: 160
    },
    {
      title: '排序值',
      dataIndex: 'sort',
      key: 'sort',
      width: 100,
      hideInSearch: true,
      render: text => <span style={{ fontFamily: 'Courier New, monospace' }}>{text}</span>
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: '启用', status: 'Success' },
        2: { text: '禁用', status: 'Default' }
      },
      render: (_, record) => {
        const status = statusMap[record.status]
        return <Tag color={status?.color || 'default'}>{status?.text || '未知'}</Tag>
      }
    },
    {
      title: '关联商品数',
      dataIndex: 'goodsNum',
      key: 'goodsNum',
      width: 120,
      hideInSearch: true,
      render: text => <span style={{ fontFamily: 'Courier New, monospace' }}>{text}</span>
    },
    {
      title: '备注',
      dataIndex: 'remark',
      key: 'remark',
      width: 200,
      hideInSearch: true,
      ellipsis: true,
      render: text => text || '-'
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 140,
      render: (_, record) => [
        <Tooltip title="编辑" key={`${record.id}-edit`}>
          <Button
            type="link"
            title="编辑"
            icon={<EditOutlined />}
            onClick={() => handleEdit(record)}
          />
        </Tooltip>,
        record.status === 1 ? (
          <Tooltip title="禁用" key={`${record.id}-disable`}>
            <Popconfirm
              title="确定要禁用该服务类别吗？"
              description={
                record.goodsNum > 0
                  ? `该类别已关联 ${record.goodsNum} 个商品，禁用后将不可用于新建/编辑商品`
                  : undefined
              }
              onConfirm={() => handleUpdateStatus(record, 2)}
              okText="确定"
              cancelText="取消"
            >
              <Button type="link" danger title="禁用" icon={<StopOutlined />} />
            </Popconfirm>
          </Tooltip>
        ) : (
          <Tooltip title="启用" key={`${record.id}-enable`}>
            <Button
              type="link"
              title="启用"
              icon={<CheckCircleOutlined />}
              style={{ color: '#52c41a' }}
              onClick={() => handleUpdateStatus(record, 1)}
            />
          </Tooltip>
        ),
        <Tooltip title="删除" key={`${record.id}-delete`}>
          <Popconfirm
            title="确定要删除该服务类别吗？"
            description={
              record.goodsNum > 0 ? '该类别已被商品引用，无法直接删除' : '删除后不可恢复'
            }
            onConfirm={() => handleDelete(record)}
            okText="确定"
            cancelText="取消"
            disabled={record.goodsNum > 0}
          >
            <Button
              type="link"
              danger
              title="删除"
              icon={<DeleteOutlined />}
              disabled={record.goodsNum > 0}
            />
          </Popconfirm>
        </Tooltip>
      ]
    }
  ]

  return (
    <>
      {/* 提示信息 */}
      <div
        style={{
          marginBottom: 16,
          padding: '12px 16px',
          background: '#e6f7ff',
          border: '1px solid #91d5ff',
          borderRadius: 8,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between'
        }}
      >
        <div style={{ color: '#096dd9', fontSize: 14 }}>
          <ExclamationCircleOutlined style={{ marginRight: 8 }} />
          商品「服务类型」字段来源于本页配置。被商品引用的类别不可直接删除。
        </div>
      </div>

      <ExcelTable
        key="service-category-list"
        columns={columns}
        requestFn={async params => {
          const { page, pageSize, name, status } = params
          return await getServiceTypeList({
            page,
            pageSize,
            name,
            status
          })
        }}
        actionRef={actionRef}
        rowSelection={false}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        toolBarRenderFn={() => [
          <Button key="add" type="primary" icon={<PlusOutlined />} onClick={handleAdd}>
            新增服务类别
          </Button>
        ]}
        scroll={{ x: 1000 }}
      />

      {/* 新增/编辑弹窗 */}
      <ModalForm
        key={editingRecord ? `edit-${editingRecord.id}` : 'add'}
        title={
          <Space>
            <AppstoreOutlined style={{ color: '#1890ff' }} />
            {modalTitle}
          </Space>
        }
        open={modalVisible}
        onOpenChange={setModalVisible}
        onFinish={handleSave}
        modalProps={{
          destroyOnClose: true
        }}
        initialValues={
          editingRecord
            ? {
                name: editingRecord.name,
                sort: editingRecord.sort,
                status: editingRecord.status,
                remark: editingRecord.remark
              }
            : {
                status: 1
              }
        }
        submitter={{
          submitButtonProps: {
            loading: formSubmitting
          }
        }}
        layout="horizontal"
        labelCol={{ flex: '0 0 100px' }}
        wrapperCol={{ flex: '1 1 auto' }}
        width={520}
      >
        <ProFormText
          name="name"
          label="类别名称"
          placeholder="例如：物品暂存"
          rules={[{ required: true, message: '请输入类别名称' }]}
        />
        <ProFormDigit
          name="sort"
          label="排序值"
          min={0}
          fieldProps={{ style: { width: 200 } }}
          rules={[{ required: true, message: '请输入排序值' }]}
        />
        <ProFormSelect
          name="status"
          label="状态"
          options={[
            { label: '启用', value: 1 },
            { label: '禁用', value: 2 }
          ]}
          rules={[{ required: true, message: '请选择状态' }]}
        />
        <ProFormText name="remark" label="备注" placeholder="可选" />
      </ModalForm>
    </>
  )
}

export default ServiceCategory
